<?php
namespace App\Http\Controllers;
use App\Models\CommunicationAttempt; use Illuminate\Http\Request; use Inertia\Inertia;
class CommunicationPreferenceController extends Controller { public function edit(Request $request) { return Inertia::render('Profile/Communication',['preference'=>$request->user()->communicationPreference()->firstOrCreate([])]); } public function update(Request $request) { $request->user()->communicationPreference()->updateOrCreate([], $request->validate(['email_enabled'=>['required','boolean'],'whatsapp_enabled'=>['required','boolean']])); return back()->with('success','Preferencias guardadas.'); } public function simulate(Request $request) { $data=$request->validate(['channel'=>['required','in:email,whatsapp'],'subject'=>['required','string','max:180'],'body'=>['nullable','string','max:2000']]); $pref=$request->user()->communicationPreference()->firstOrCreate([]); $enabled=$data['channel']==='email'?$pref->email_enabled:$pref->whatsapp_enabled; CommunicationAttempt::create(['user_id'=>$request->user()->id,...$data,'status'=>$enabled?'simulated':'disabled']); return back()->with('success',$enabled?'Intento simulado registrado.':'Canal desactivado; intento registrado.'); } }
